import {PaperScene} from './scene.js';
import {levels,initialState,neighbors,complete,moveState,foldState,pathTo,solve} from './levels.js';
const $=s=>document.querySelector(s);const roman=['Ⅰ','Ⅱ','Ⅲ'];
let index=0,state,history=[],busy=false,scene,startTime=Date.now(),toastTimer,victoryTimer,sound=false,audioCtx,ambienceTimer,progress={};
try{progress=JSON.parse(localStorage.getItem('foldlight-progress')||'{}');if(typeof progress!=='object'||!progress)progress={}}catch{progress={}}
function tone(freq=440,type='sine',duration=.18,volume=.06){if(!sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioCtx.currentTime);gain.gain.setValueAtTime(0,audioCtx.currentTime);gain.gain.linearRampToValueAtTime(volume,audioCtx.currentTime+.012);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain).connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch{}}
function chime(){[523.25,659.25,783.99].forEach((f,i)=>setTimeout(()=>tone(f,'sine',.65,.045),i*110))}
function toast(message,duration=3300){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),duration)}
function persist(){try{localStorage.setItem('foldlight-progress',JSON.stringify(progress));localStorage.setItem('foldlight-current',String(index))}catch{}}
function sync(){const level=levels[index];$('#chapter-number').textContent=String(index+1).padStart(2,'0');$('#chapter-title').textContent=level.title;$('#chapter-subtitle').textContent=level.subtitle;$('#objective-text').textContent=level.description;$('#realm-name').textContent=level.realm;$('#star-count').textContent=`✦ ${state.stars.length} / ${level.nodes.filter(n=>n.star).length}`;$('#key-count').hidden=!level.nodes.some(n=>n.key);$('#key-count').textContent=state.key?'⚿ 已取得钥匙':'⚿ 寻找钥匙';$('#switch-count').hidden=!level.nodes.some(n=>n.switch);$('#switch-count').textContent=state.switch?'◇ 纸扣已唤醒':'◇ 寻找纸扣';$('#moves').textContent=String(state.moves).padStart(2,'0');$('#folds').textContent=String(state.foldCount).padStart(2,'0');$('#undo-btn').disabled=!history.length||busy;$('#restart-btn').disabled=busy;
  $('#fold-controls').innerHTML=level.folds.map((f,i)=>{const available=f.stations.includes(state.at);return `<button class="fold-control ${state.folds[i]?'active':''}" data-fold="${i}" style="--fold-color:#${f.color.toString(16)}" aria-label="${f.name}，${state.folds[i]?'已折起':'已平展'}，${available?'可切换':'需要前往折叠台'}" ${busy?'disabled':''}><span class="fold-symbol">${roman[i]}</span><span class="fold-text"><b>${f.name}</b><small>${available?(state.folds[i]?'已折起 · 展开':'已平展 · 折叠'):'前往 '+roman[i]+' 折叠台'}</small></span><span class="keycap">${i+1}</span></button>`}).join('');$('#fold-controls').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>toggleFold(Number(b.dataset.fold))));
  const available=level.folds.some(f=>f.stations.includes(state.at));$('#fold-note').textContent=available?'你站在折叠台上，可以改变世界了。':'只有站在对应折叠台上，才能改变道路。';
  $('#chapter-dots').innerHTML=levels.map((l,i)=>`<button class="${index===i?'selected':progress[i]?'done':''}" data-index="${i}" title="${l.title}" aria-label="第 ${i+1} 章：${l.title}"></button>`).join('');$('#chapter-dots').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>loadLevel(Number(b.dataset.index))));scene?.sync(state);
}
function loadLevel(i){if(busy)return;clearTimeout(victoryTimer);index=i;state=initialState(levels[i]);history=[];startTime=Date.now();$('#modal').close();scene.load(levels[i],state);sync();persist();toast(levels[i].intro,4200)}
async function goTo(id){if(busy||$('#modal').open)return{error:'请等待当前动作完成。'};const level=levels[index];if(!level.nodes.some(n=>n.id===id))throw new Error('未知岛屿。');if(id===state.at){const station=level.folds.findIndex(f=>f.stations.includes(id));if(station>=0)toast(`你已在 ${roman[station]} 号折叠台。点击右侧折痕，或按 ${station+1}。`);else toast('点击连接着道路的另一座纸岛。');return{state}}const path=pathTo(level,state,id);if(!path){tone(150,'sine',.18,.025);toast('路还没有连起来。试着回到折叠台，改变折痕。');return{error:'道路未连通'}}busy=true;sync();for(let j=1;j<path.length;j++){history.push(structuredClone(state));const old=state;await scene.travel([state.at,path[j]]);state=moveState(level,state,path[j]);scene.flash(state.at);tone(310+j*45,'sine',.16,.028);if(state.stars.length>old.stars.length){chime();toast(`接住一颗星光 ✦  ${state.stars.length} / ${level.nodes.filter(n=>n.star).length}`)}if(state.key&&!old.key){chime();toast('找到星光钥匙，金色的门已经为你打开。')}if(state.switch&&!old.switch){chime();toast('青色纸扣被唤醒，远方的束缚解开了。')}scene.sync(state);sync();}
 busy=false;sync();if(complete(level,state))win();else if(state.at===level.goal)toast(`光之门还在等你。还有 ${level.nodes.filter(n=>n.star).length-state.stars.length} 颗星光没有收集。`,4200);return{state:structuredClone(state)};
}
async function toggleFold(i){if(busy||$('#modal').open)return{error:'请等待当前动作完成。'};if(!Number.isInteger(i)||!levels[index].folds[i])throw new Error('未知折痕。');const f=levels[index].folds[i];if(!f.stations.includes(state.at)){toast(`请先走到 ${roman[i]} 号折叠台，再改变这道折痕。`);f.stations.forEach(id=>scene.flash(id));return{error:'未站在对应折叠台'}}history.push(structuredClone(state));state=foldState(levels[index],state,i);busy=true;sync();tone(state.folds[i]?280:220,'triangle',.5,.045);await new Promise(r=>setTimeout(r,650));busy=false;sync();return{state:structuredClone(state)}}
function undo(){if(busy||!history.length)return;clearTimeout(victoryTimer);state=history.pop();scene.sync(state,true);sync();toast('时间轻轻退回了一步。',1800)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function showChapters(){if(busy)return;modal(`<span class="modal-kicker">SIX LITTLE WORLDS</span><h2>沿着折痕，慢慢旅行</h2><p>六片纸境，六种相遇。可以按顺序探索，也可以选择想去的远方。</p><div class="chapter-grid">${levels.map((l,i)=>`<button class="chapter-card" data-level="${i}"><span class="num">0${i+1} ${progress[i]?'· ✦ 已完成':''}</span><strong>${l.title.split(' · ')[1]}</strong><small>${l.realm} · ${l.folds.length} 道折痕</small></button>`).join('')}</div><p style="font-size:11px;margin-top:22px">完成记录保存在这台设备的浏览器中。</p>`);$('#modal-content').querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>loadLevel(Number(b.dataset.level))))}
function showHelp(){modal(`<span class="modal-kicker">A SMALL GUIDE TO FOLDING</span><h2>你好，纸片旅人。</h2><p>你是小纸灵。这些漂浮的纸岛曾经相连，沿着折痕，把它们重新带到一起吧。</p><div class="help-row"><span>⌁</span><div><strong>沿着纸路走</strong><p>点击想去的纸岛。道路连通时，精灵会自动沿路前行。星光和钥匙会在经过时收集，青色纸扣踩下后永久开启。</p></div></div><div class="help-row"><span>◇</span><div><strong>站上折叠台，改变世界</strong><p>到达标有 Ⅰ、Ⅱ 或 Ⅲ 的纸岛后，点击对应折痕或按数字 1、2、3。折起一边时，另一边的道路可能会收起。行走与折叠动画期间不能再次操作。</p></div></div><div class="help-row"><span>✦</span><div><strong>把星光带到光之门</strong><p>收齐本章星光，再到达发光的门。遇到金色栅栏需要钥匙，青色栅栏需要先唤醒纸扣。</p></div></div><div class="help-row"><span>↶</span><div><strong>没有失败，只有下一种折法</strong><p>Z 撤销 · R 重来 · Q / E 旋转视角 · 方向键选择可达的相邻纸岛。也可以拖动空白处环绕观察、滚轮缩放。「一点灵感」会提示当前的下一步。</p></div></div><button class="primary-button" id="help-done">开始我的旅行</button>`);$('#help-done').onclick=()=>$('#modal').close()}
function hint(){if(busy)return;const result=solve(levels[index],state);if(!result?.length){toast('星光已经到齐，光之门就在脚下。');return}const a=result[0];if(a.type==='fold'){const f=levels[index].folds[a.id];toast(`一点灵感：就在这里，${state.folds[a.id]?'展开':'折起'}「${f.name}」。`,5200);const b=$(`[data-fold="${a.id}"]`);b.animate([{boxShadow:'0 0 0 0 #e7ba9960'},{boxShadow:'0 0 0 9px #e7ba9900'}],{duration:900,iterations:3})}else{scene.flash(a.id);const n=levels[index].nodes.find(n=>n.id===a.id);let name=n.id===levels[index].goal?'光之门':n.key&&!state.key?'有钥匙的纸岛':n.star&&!state.stars.includes(n.id)?'发光的星光纸岛':n.label||'亮起圆环的纸岛';toast(`一点灵感：先走向${name}。`,5200)}}
function win(){const level=levels[index],seconds=Math.round((Date.now()-startTime)/1000);const old=progress[index];progress[index]={folds:old?Math.min(old.folds,state.foldCount):state.foldCount,moves:old?Math.min(old.moves,state.moves):state.moves};persist();chime();const last=index===levels.length-1;victoryTimer=setTimeout(()=>{modal(`<div class="success"><span class="modal-kicker">${last?'EVERY FOLD LEADS HOME':'CHAPTER COMPLETE'}</span><div class="success-symbol">✧</div><h2>${last?'把星光，折进了家。':'这一岸，终于遇见那一岸。'}</h2><p>${last?'六片纸境的旅程已经完成。<br>谢谢你，让散落的星光重新相遇。':'小小的折痕，连接了原本遥远的地方。<br>新的纸世界，正等你轻轻展开。'}</p><div class="score-row"><div><b>${state.stars.length}</b><span>颗星光</span></div><div><b>${state.foldCount}</b><span>次折叠</span></div><div><b>${state.moves}</b><span>步旅程</span></div><div><b>${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}</b><span>旅行时间</span></div></div><button class="primary-button" id="next-level">${last?'回看我的旅程':'展开下一章'}</button><button class="secondary-button" id="replay">再折一次</button></div>`);$('#next-level').onclick=()=>last?showChapters():loadLevel(index+1);$('#replay').onclick=()=>loadLevel(index);sync()},550)}
$('#modal .modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#chapters-btn').onclick=showChapters;$('#help-btn').onclick=showHelp;$('#undo-btn').onclick=undo;$('#restart-btn').onclick=()=>loadLevel(index);$('#hint-btn').onclick=hint;$('#rotate-left').onclick=()=>scene.rotate(-1);$('#rotate-right').onclick=()=>scene.rotate(1);$('#camera-reset').onclick=()=>scene.resetCamera();$('#sound-btn').onclick=()=>{sound=!sound;$('#sound-btn').textContent=sound?'♪':'♫';$('#sound-btn').style.color=sound?'var(--accent)':'';$('#sound-btn').setAttribute('aria-label',sound?'关闭声音':'开启声音');if(sound){chime();ambienceTimer=setInterval(()=>tone([130.81,164.81,196,261.63][Math.floor(Math.random()*4)],'sine',3,.012),2600)}else clearInterval(ambienceTimer);toast(sound?'纸境的声音，轻轻响起。':'声音已关闭。',1800)};
addEventListener('keydown',e=>{if($('#modal').open)return;const k=e.key.toLowerCase();if(k==='z')undo();else if(k==='r')loadLevel(index);else if(k==='q')scene.rotate(-1);else if(k==='e')scene.rotate(1);else if(['1','2','3'].includes(k)&&levels[index].folds[Number(k)-1])toggleFold(Number(k)-1);else if(['arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();const origin=scene.projectNode(state.at);const aim={arrowup:[0,-1],arrowdown:[0,1],arrowleft:[-1,0],arrowright:[1,0]}[k];const options=neighbors(levels[index],state).map(id=>{const p=scene.projectNode(id),dx=p.x-origin.x,dy=p.y-origin.y;return{id,score:(dx*aim[0]+dy*aim[1])/Math.hypot(dx,dy)}}).sort((a,b)=>b.score-a.score);if(options[0]?.score>.1)goTo(options[0].id)}});
try{scene=new PaperScene($('#world'),goTo,toggleFold);let last=0;try{last=Number(localStorage.getItem('foldlight-current')||0)}catch{}loadLevel(Number.isInteger(last)&&last>=0&&last<levels.length?last:0);$('#loading').classList.add('hidden');setTimeout(()=>$('#loading').remove(),700)}catch(error){$('#loading').innerHTML='<div class="loading-mark">◇</div><h2>纸世界暂时无法展开</h2><p>请使用支持 WebGL 的浏览器，并开启硬件加速后刷新。</p><button class="primary-button" onclick="location.reload()">再试一次</button>';console.error(error)}
// Structured tools use exactly the same actions and game state as the visible controls.
const readState=()=>({chapter:index+1,title:levels[index].title,...structuredClone(state),reachable:neighbors(levels[index],state),foldStations:levels[index].folds.map((f,i)=>({id:i+1,name:f.name,available:f.stations.includes(state.at)}))});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const registrations=[{name:'read_paper_world',description:'Read the current chapter, spirit position, collected stars and available paths.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>readState()},{name:'move_paper_spirit',description:'Move the spirit along connected paths to a named island and collect items along the way.',inputSchema:{type:'object',properties:{island:{type:'string'}},required:['island'],additionalProperties:false},execute:async({island})=>{if(typeof island!=='string')throw new Error('island must be a string');return goTo(island)}},{name:'toggle_paper_fold',description:'Fold or unfold one crease while standing at its corresponding folding station.',inputSchema:{type:'object',properties:{crease:{type:'integer',minimum:1,maximum:3}},required:['crease'],additionalProperties:false},execute:async({crease})=>{if(!Number.isInteger(crease)||crease<1||crease>levels[index].folds.length)throw new Error('Invalid crease');return toggleFold(crease-1)}}];for(const t of registrations){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
// A read-only inspection surface supports local verification without alternate game logic.
window.foldlight={read:readState,project:id=>scene.projectNode(id),get busy(){return busy}};
